-- ============================================================
-- SEED: Módulo 12 — Conditional Types 2 & 3 (B1)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'conditional-2-3';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo conditional-2-3 não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: Type 2 - if + past simple, would + base verb
  (cid,1,1,'gap_fill','If I ___ (have) more time, I ___ (study) an additional language.','had / would study',NULL,'Type 2: if + past simple, would + base verb. Unreal present/future situation.','medium'),
  (cid,1,2,'gap_fill','She ___ (apply) for the scholarship if she ___ (meet) the eligibility requirements.','would apply / met',NULL,'Type 2: would + base verb / if + past simple.','medium'),
  (cid,1,3,'multiple_choice','Choose the correct Type 2 conditional.','If the university offered more scholarships, more international students would attend.','["If the university offers more scholarships, more international students would attend (mixed error).","If the university offered more scholarships, more international students will attend (Type 1 error).","If the university offered more scholarships, more international students would attend.","If the university had offered more scholarships, more international students would attend (Type 3)."]','If + past simple, would + base verb = Type 2.','medium'),
  (cid,1,4,'gap_fill','If researchers ___ (be) able to eliminate all bias, studies ___ (be) perfectly reliable.','were / would be',NULL,'Type 2 with "be": use "were" for all persons (formal). Would be for result.','medium'),
  (cid,1,5,'gap_fill','What ___ you ___ (do) if you ___ (discover) a flaw in your methodology?','would / do / discovered',NULL,'Type 2 question: What would + subject + base verb + if + past simple?','hard'),
  (cid,1,6,'multiple_choice','Which sentence uses "were" correctly in a Type 2 conditional?','If the sample were larger, the results would be more generalizable.','["If the sample was larger, the results will be more generalizable (Type 1 error).","If the sample were larger, the results would be more generalizable.","If the sample was larger, the results would be more generalizable. (also acceptable in informal English)","If the sample is larger, the results would be more generalizable."]','Formal Type 2: "were" for all persons.','hard'),
  (cid,1,7,'gap_fill','If every country ___ (commit) to carbon neutrality, global warming ___ (slow) significantly.','committed / would slow',NULL,'Unreal/hypothetical global scenario: Type 2 conditional.','medium'),

  -- BLOCK 2: Type 2 - unreal present/future
  (cid,2,8,'multiple_choice','Which sentence describes an UNREAL present situation (Type 2)?','If I were the prime minister, I would invest heavily in education.','["If I become the prime minister, I will invest in education (Type 1 — possible).","If I were the prime minister, I would invest heavily in education.","If I was the prime minister, I invested in education (incorrect).","If I am the prime minister, I would invest in education (mixed error)."]','If I were = unreal present. I am not the prime minister.','medium'),
  (cid,2,9,'gap_fill','If the lab equipment ___ (not/be) so expensive, more universities ___ (can/afford) it.','weren''t / could afford',NULL,'Type 2 with "could" in result clause for ability/possibility.','hard'),
  (cid,2,10,'multiple_choice','Choose the correct Type 2 response to: "Why don''t you travel more?" "If I ___ more money, I ___ travel more."','had / would','["have / would","had / will","had / would","have / will"]','If + had (past simple), would + base verb.','medium'),
  (cid,2,11,'gap_fill','If she ___ (not/have) to work part-time, she ___ (be able to) devote more time to research.','didn''t have / would be able to',NULL,'Type 2 negative condition: didn''t + base verb; would be able to in result.','hard'),
  (cid,2,12,'multiple_choice','Identify the error: "If I would study harder, I would pass the exam."','would study should be studied','["I should be me","would pass is wrong","would study should be studied","harder should be more hard"]','Never use "would" in the if-clause. Use past simple.','medium'),
  (cid,2,13,'gap_fill','What ___ (might/happen) if scientists ___ (have) unlimited funding?','might happen / had',NULL,'"Might" in result clause for less certain Type 2 outcome.','hard'),
  (cid,2,14,'multiple_choice','Which modal can replace "would" in the result clause of a Type 2 conditional?','could (for ability)','["will","am going to","could (for ability)","was going to"]','"Could" in Type 2 result clause = would be able to / it might be possible.','hard'),

  -- BLOCK 3: Type 3 - if + past perfect, would have + past participle
  (cid,3,15,'gap_fill','If she ___ (study) harder, she ___ (pass) the exam.','had studied / would have passed',NULL,'Type 3: if + past perfect, would have + past participle. Unreal past.','medium'),
  (cid,3,16,'multiple_choice','Choose the correct Type 3 conditional.','If the researchers had controlled the variables, the results would have been more reliable.','["If the researchers controlled the variables, the results would have been more reliable (mixed error).","If the researchers had controlled the variables, the results will have been more reliable (error).","If the researchers had controlled the variables, the results would have been more reliable.","If the researchers had controlled the variables, the results had been more reliable (error)."]','If + had + past participle, would have + past participle.','medium'),
  (cid,3,17,'gap_fill','The accident ___ (not/happen) if they ___ (follow) the safety protocols.','wouldn''t have happened / had followed',NULL,'Type 3 negative: wouldn''t have + past participle / if + had + past participle.','medium'),
  (cid,3,18,'multiple_choice','What does a Type 3 conditional express?','An unreal or hypothetical situation in the past and its imagined result.','["A real situation in the future","A possible situation in the present","An unreal or hypothetical situation in the past and its imagined result.","A general truth or scientific fact"]','Type 3 = looking back at past and imagining a different outcome.','medium'),
  (cid,3,19,'gap_fill','If Darwin ___ (not/travel) to the Galápagos, he might ___ (never/develop) his theory of natural selection.','hadn''t traveled / have never developed',NULL,'Type 3 with might have for speculative past result.','hard'),
  (cid,3,20,'multiple_choice','Identify the error: "If they would have invested earlier, the company would have survived."','would have invested should be had invested','["the company is wrong","would have survived should be would survived","would have invested should be had invested","earlier should be sooner"]','Never use "would have" in the if-clause. Use had + past participle.','medium'),
  (cid,3,21,'gap_fill','She ___ (not/make) such an error if she ___ (proofread) the paper carefully.','wouldn''t have made / had proofread',NULL,'Type 3: wouldn''t have + past participle / if + had + past participle.','medium'),

  -- BLOCK 4: Type 3 - unreal past
  (cid,4,22,'gap_fill','If Flemming ___ (not/leave) the petri dish contaminated, he ___ (never/discover) penicillin.','hadn''t left / would never have discovered',NULL,'Historical counterfactual: Type 3 conditional.','hard'),
  (cid,4,23,'multiple_choice','Which sentence correctly uses could have in a Type 3 conditional?','If the team had prepared better, they could have won the competition.','["If the team prepared better, they could have won the competition (mixed error — Type 3 if clause missing).","If the team has prepared better, they could have won the competition.","If the team had prepared better, they could have won the competition.","If the team had prepared better, they could win the competition (mixed conditional)."]','If + had + past participle, could have + past participle.','hard'),
  (cid,4,24,'gap_fill','What would you have done if you ___ (be) in that situation?','had been',NULL,'Type 3 question: What would you have done if + had + past participle?','medium'),
  (cid,4,25,'multiple_choice','Choose the correct Type 3 conditional in academic context.','If the initial sample had been larger, the study would have produced more conclusive results.','["If the initial sample was larger, the study would have produced more conclusive results (mixed error).","If the initial sample had been larger, the study would have produced more conclusive results.","If the initial sample had been larger, the study will have produced more conclusive results.","If the initial sample had been larger, the study would produce more conclusive results (Type 2 result clause)."]','If + had been, would have + past participle.','hard'),
  (cid,4,26,'gap_fill','The economic crisis ___ (might/be) avoided if the government ___ (act) sooner.','might have been / had acted',NULL,'"Might have been" for speculative past result; passive voice.','hard'),
  (cid,4,27,'multiple_choice','Type 3 conditionals are commonly used in academic writing to:','Evaluate past decisions, actions, or events by imagining alternative outcomes.','["Predict future events","Describe habits and routines","Evaluate past decisions, actions, or events by imagining alternative outcomes.","Express present ability and permission"]','Type 3 = critical analysis of past events.','hard'),
  (cid,4,28,'gap_fill','If the clinical trial ___ (be) designed differently, researchers ___ (obtain) more meaningful data.','had been / would have obtained',NULL,'Passive Type 3: had been + past participle → would have obtained.','hard'),

  -- BLOCK 5: mixed conditionals
  (cid,5,29,'gap_fill','If she ___ (study) medicine (past), she ___ (be) a doctor now.','had studied / would be',NULL,'Mixed conditional: if + past perfect (past condition) → would + base verb (present result).','hard'),
  (cid,5,30,'multiple_choice','Which sentence is a MIXED conditional?','If he had chosen a different career, he wouldn''t be working in academia today.','["If he had chosen a different career, he wouldn''t have worked in academia (Type 3 — past result).","If he chose a different career, he wouldn''t be working in academia (Type 2 — unreal present).","If he had chosen a different career, he wouldn''t be working in academia today.","If he chooses a different career, he won''t be working in academia (Type 1)."]','Past condition (had chosen) + present result (wouldn''t be working) = mixed conditional.','hard'),
  (cid,5,31,'gap_fill','If they ___ (build) the railway line in the 1980s (past), the city ___ (have) better transport infrastructure now.','had built / would have',NULL,'Past condition → present result: mixed conditional.','hard'),
  (cid,5,32,'multiple_choice','Identify the mixed conditional.','If she had taken the advanced course last semester, she would understand this material more easily now.','["If she takes the advanced course, she will understand this material (Type 1).","If she took the advanced course, she would understand this material (Type 2).","If she had taken the advanced course last semester, she would understand this material more easily now.","If she had taken the advanced course last semester, she would have understood this material (Type 3)."]','Had taken (past) → would understand (present) = mixed conditional.','hard'),
  (cid,5,33,'gap_fill','She ___ (not/be) so stressed now if she ___ (not/leave) her preparation to the last minute.','wouldn''t be / hadn''t left',NULL,'Present result (wouldn''t be) from past condition (hadn''t left) = mixed conditional.','hard'),
  (cid,5,34,'multiple_choice','Which type of conditional combines past condition with present result?','Mixed conditional','["Type 1","Type 2","Type 3","Mixed conditional"]','Mixed conditional: past condition (if + past perfect) + present result (would + base verb).','medium'),
  (cid,5,35,'gap_fill','If the university ___ (invest) in renewable energy earlier (past), it ___ (not/struggle) with rising energy costs now.','had invested / wouldn''t be struggling',NULL,'Past condition + present ongoing result = mixed conditional.','hard'),

  -- BLOCK 6: unless and wish
  (cid,6,36,'multiple_choice','Which sentence with "unless" is correct in a Type 2 context?','Unless the government increased funding, research would stagnate.','["Unless the government will increase funding, research would stagnate.","Unless the government increased funding, research would stagnate.","Unless the government had increased funding, research would stagnate (Type 3).","Unless the government increases funding, research will stagnate (Type 1)."]','Unless + past simple, would + base verb = Type 2 unless.','hard'),
  (cid,6,37,'gap_fill','I wish I ___ (speak) three languages like my colleague.','spoke',NULL,'"Wish + past simple" for present wishes about unreal situations.','medium'),
  (cid,6,38,'multiple_choice','Which sentence correctly uses "wish" about the PAST?','She wishes she had chosen a different topic for her dissertation.','["She wishes she chose a different topic (present wish about present).","She wishes she would choose a different topic (future wish — use would).","She wishes she had chosen a different topic for her dissertation.","She wished she has chosen a different topic."]','"Wish + past perfect" for regrets about past situations.','hard'),
  (cid,6,39,'gap_fill','He wishes the university ___ (offer) more financial support for PhD students.','offered',NULL,'"Wish + past simple" for unreal present wishes.','medium'),
  (cid,6,40,'multiple_choice','Choose the correct "wish" sentence about the PRESENT.','I wish I had more time to prepare for the TOEFL.','["I wish I have more time to prepare for the TOEFL.","I wish I had more time to prepare for the TOEFL.","I wish I would have more time to prepare.","I wish I will have more time to prepare."]','"Wish + past simple" (had) for unreal present wishes.','medium'),
  (cid,6,41,'gap_fill','She wishes she ___ (not/make) such a fundamental error in the analysis.','hadn''t made',NULL,'"Wish + past perfect (negative)" for past regrets.','hard'),
  (cid,6,42,'multiple_choice','Which sentence correctly expresses a future wish or complaint using "wish"?','I wish she would stop interrupting during presentations.','["I wish she will stop interrupting (future — wrong form).","I wish she would stop interrupting during presentations.","I wish she stopped interrupting (present wish about present habit — also acceptable).","I wish she had stopped interrupting (regret about past)."]','"Wish + would + base verb" for wanting change in someone''s behavior.','hard'),

  -- BLOCK 7: Type 2 vs Type 3 contrast
  (cid,7,43,'multiple_choice','Identify whether this is Type 2 or Type 3: "If the data had been more complete, the analysis would have been easier."','Type 3 — unreal past situation','["Type 2 — unreal present situation","Type 3 — unreal past situation","Mixed conditional","Type 1 — real future"]','If + had been (past perfect) → would have been (would have + past participle) = Type 3.','medium'),
  (cid,7,44,'gap_fill','Type 2: If I ___ (be) a scientist, I ___ (study) quantum physics. Type 3: If I ___ (be) a scientist, I ___ (choose) a different specialization.','were / would study / had been / would have chosen',NULL,'Type 2: past simple in if-clause; Type 3: past perfect in if-clause.','hard'),
  (cid,7,45,'multiple_choice','Which sentence is Type 2 (not Type 3)?','If the curriculum were more flexible, students would have more academic freedom.','["If the curriculum had been more flexible, students would have had more freedom (Type 3).","If the curriculum were more flexible, students would have more academic freedom.","If the curriculum had been more flexible, students would have more freedom (mixed).","If the curriculum was more flexible, students will have more freedom (Type 1 with error)."]','If + were (past simple), would + base verb = Type 2.','hard'),
  (cid,7,46,'gap_fill','If global temperatures ___ (not/rise) so rapidly (reality = they are), ecosystems ___ (not/be) under such extreme pressure.','weren''t rising / wouldn''t be',NULL,'Type 2 with continuous in if-clause for ongoing unreal situation.','hard'),
  (cid,7,47,'multiple_choice','"If the experiment had used a control group, the conclusions would have been more valid." This is Type ___?','3','["1","2","3","Mixed"]','Had used (past perfect in if-clause) + would have been = Type 3.','easy'),
  (cid,7,48,'gap_fill','Researchers argue that if the original study ___ (replicate) with a larger sample, the results might ___ (differ) significantly.','had been replicated / have differed',NULL,'Type 3 in academic passive: if + had been + past participle, might have + past participle.','hard'),
  (cid,7,49,'multiple_choice','Which sentence correctly combines Type 2 and Type 3 (mixed)?','If she had been accepted into the program (past), she would be finishing her thesis now.','["If she had been accepted into the program (past), she would have been finishing her thesis (Type 3).","If she had been accepted into the program (past), she would be finishing her thesis now.","If she was accepted into the program (past), she would be finishing her thesis (Type 2 error).","If she had accepted the program (past), she is finishing her thesis (tense error)."]','Past perfect condition (had been accepted) + present continuous result (would be finishing) = mixed.','hard'),

  -- BLOCK 8: mixed review - Types 2 & 3
  (cid,8,50,'multiple_choice','Choose the correct sentence.','If the infrastructure had been modernized decades ago, the city would not be facing such severe traffic problems today.','["If the infrastructure was modernized decades ago, the city would not face traffic problems.","If the infrastructure had been modernized decades ago, the city would not be facing such severe traffic problems today.","If the infrastructure had been modernized decades ago, the city would not have been facing traffic problems (Type 3 only).","If the infrastructure modernized decades ago, the city would not face traffic problems."]','Mixed: past condition (had been modernized) + present ongoing result (would not be facing).','hard'),
  (cid,8,51,'gap_fill','If the study ___ (not/be) flawed, its conclusions ___ (gain) wider acceptance.','hadn''t been / would have gained',NULL,'Type 3: hadn''t been + past participle → would have + past participle.','medium'),
  (cid,8,52,'multiple_choice','Identify the error: "If they would have acted faster, the situation would have been avoided."','would have acted should be had acted','["situation should be situations","would have been should be would be","would have acted should be had acted","the is unnecessary"]','In the if-clause of Type 3, use past perfect (had acted), not "would have".','medium'),
  (cid,8,53,'gap_fill','I wish I ___ (not/spend) so much time on the introduction — now I don''t have enough for the conclusion.','hadn''t spent',NULL,'"Wish + past perfect" for regret about past action.','hard'),
  (cid,8,54,'multiple_choice','Which sentence best expresses a regret about a past academic decision?','If I had chosen a narrower research topic, I would have completed the thesis on time.','["If I choose a narrower topic, I will complete the thesis on time (Type 1).","If I chose a narrower topic, I would complete the thesis on time (Type 2).","If I had chosen a narrower research topic, I would have completed the thesis on time.","If I would choose a narrower topic, I would have completed on time (error)."]','Type 3 for academic regret about past choices.','hard'),
  (cid,8,55,'gap_fill','Unless the government ___ (implement) stricter regulations (hypothetical), pollution levels ___ (continue) to rise.','implemented / would continue',NULL,'Type 2 with unless: unless + past simple, would + base verb.','hard'),
  (cid,8,56,'multiple_choice','Which sentence uses "could have" correctly in a Type 3 conditional?','The team could have published earlier if the peer review process hadn''t been delayed.','["The team could have published earlier if the peer review process isn''t delayed (Type 1 error).","The team could published earlier if the peer review process hadn''t been delayed.","The team could have published earlier if the peer review process hadn''t been delayed.","The team could have published earlier if the peer review process wouldn''t have been delayed."]','Could have + past participle; if + hadn''t + past participle.','hard'),

  -- BLOCK 9: TOEFL academic contexts
  (cid,9,57,'multiple_choice','[TOEFL Reading] Which Type 2 sentence best fits an academic argument about current policy?','If governments allocated more resources to preventive healthcare, chronic disease rates would decline substantially.','["If governments had allocated more resources, chronic disease rates would have declined (Type 3 — past).","If governments allocate more resources, chronic disease rates will decline (Type 1 — real/possible).","If governments allocated more resources to preventive healthcare, chronic disease rates would decline substantially.","If governments were allocating more resources, chronic disease rates would be declining."]','Type 2 for hypothetical policy recommendation: allocated (past simple) → would decline.','hard'),
  (cid,9,58,'gap_fill','[TOEFL Listening] The professor says: "If the original researchers ___ (include) a control group, we ___ (have) much clearer data today."','had included / would have',NULL,'"Had included" (Type 3 past condition) + "would have" (implied present mixed result).','hard'),
  (cid,9,59,'multiple_choice','[TOEFL Reading] Which sentence correctly critiques a historical decision using Type 3 conditional?','If early scientists had accepted the germ theory of disease sooner, thousands of lives might have been saved.','["If early scientists accepted the germ theory sooner, thousands of lives might be saved (Type 2).","If early scientists had accepted the germ theory of disease sooner, thousands of lives might have been saved.","If early scientists would have accepted the germ theory sooner, lives might have been saved (error).","If early scientists had been accepting the germ theory sooner, lives had been saved."]','Type 3: had accepted + might have been saved (passive).','hard'),
  (cid,9,60,'gap_fill','[TOEFL Reading] The author argues that if colonial powers ___ (not/exploit) African resources so extensively, the continent ___ (develop) more equitably.','had not exploited / would have developed',NULL,'Type 3 for historical counterfactual analysis.','hard'),
  (cid,9,61,'multiple_choice','[TOEFL Listening] The professor asks: "What would happen if we removed all trade barriers?" This is a ___','Type 2 conditional question.','["Type 1 conditional question","Type 2 conditional question.","Type 3 conditional question","Mixed conditional question"]','"What would happen if we removed" = What would + base verb, if + past simple = Type 2.','medium'),
  (cid,9,62,'gap_fill','[TOEFL Reading] If the discovery of antibiotics ___ (not/occur) in the 20th century, modern surgery and cancer treatment ___ (not/be) possible.','had not occurred / would not have been',NULL,'Type 3 historical counterfactual with passive.','hard'),
  (cid,9,63,'multiple_choice','[TOEFL Listening] The professor describes a current crisis and says: "If we ___ taken action thirty years ago, we ___ be in this situation today." What goes in the blanks?','had / wouldn''t','["have / won''t","had / wouldn''t","would have / wouldn''t","had / wouldn''t have"]','Mixed conditional: had taken (past perfect) + wouldn''t be (present result).','hard'),

  -- BLOCK 10: TOEFL production tasks
  (cid,10,64,'multiple_choice','[TOEFL Reading] Which sentence demonstrates the most sophisticated use of conditional types in academic writing?','If the study had been designed with a randomized control group, the findings would have been more conclusive; moreover, current replication efforts might have been unnecessary.','["If the study is designed with a control group, the findings will be more conclusive.","If the study had been designed with a randomized control group, the findings would have been more conclusive; moreover, current replication efforts might have been unnecessary.","If the study was designed with a control group, the findings would be more conclusive.","If the study designs a control group, the findings would have been more conclusive."]','Type 3: had been designed → would have been + might have been (all past counterfactual).','hard'),
  (cid,10,65,'gap_fill','[TOEFL Reading] The author concludes: "If policymakers ___ (recognize) the warning signs earlier (past), the financial crisis ___ (not/escalate) to such catastrophic proportions, and millions of people ___ (not/lose) their savings."','had recognized / would not have escalated / would not have lost',NULL,'Type 3 for historical policy critique with multiple result clauses.','hard'),
  (cid,10,66,'multiple_choice','[TOEFL Speaking — 45s] You are asked: "How would scientific research be different if there were no ethical restrictions?" Which response best uses Type 2 conditional?','If there were no ethical restrictions, research would advance more rapidly in some areas, but it could lead to serious harm to human subjects and would ultimately undermine public trust in science.','["If there are no ethical restrictions, research will advance more rapidly (Type 1 — not hypothetical).","If there were no ethical restrictions, research would advance more rapidly in some areas, but it could lead to serious harm to human subjects and would ultimately undermine public trust in science.","If there had been no ethical restrictions, research would have advanced more rapidly (Type 3 — past).","If there would be no ethical restrictions, research could advance (error: would in if-clause)."]','Type 2: if + were (past simple), would/could + base verb for unreal present scenario.','hard'),
  (cid,10,67,'production','[TOEFL Speaking — 45s] Reflect on an important historical event. Describe what would have happened if a key decision had been made differently. Use Type 3 conditional for the past counterfactual, and a mixed conditional to describe how the present would be different as a result.','',NULL,'Type 3: if + past perfect, would have + past participle; Mixed: if + past perfect, would + base verb.','hard'),
  (cid,10,68,'production','[TOEFL Writing] Write a paragraph (4-5 sentences) analyzing a past scientific, social, or political failure. Use: one Type 2 (hypothetical alternative now), one Type 3 (unreal past), one mixed conditional, and one "wish" sentence expressing regret.','',NULL,'Integrate Type 2, Type 3, mixed conditionals, and wish in critical academic analysis.','hard'),
  (cid,10,69,'multiple_choice','[TOEFL Writing] Which sentence best opens a critical analysis paragraph using Type 3 conditional?','Had the government acted on early warnings, the public health crisis would not have reached its current magnitude.','["If the government acts on early warnings, the crisis will not reach its current magnitude (Type 1).","If the government had acted on early warnings, the crisis would not reach its current magnitude (mixed).","Had the government acted on early warnings, the public health crisis would not have reached its current magnitude.","If the government would have acted on early warnings, the crisis would not have reached this magnitude (error)."]','Inverted Type 3: Had + subject + past participle (formal academic style without "if").','hard'),
  (cid,10,70,'production','[TOEFL Writing] Write a 5-sentence paragraph critiquing a historical or contemporary policy decision. Include: one standard Type 3 conditional, one inverted Type 3 (Had + subject + past participle...), one mixed conditional showing present consequence of past decision, one "wish" sentence, and one Type 2 suggesting an alternative policy.','',NULL,'Demonstrate mastery of all advanced conditional forms in sophisticated academic writing.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
